require_once __DIR__.'/includes/db.php';if(current_user()){header('Location: index.php');exit;}$err='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$s=db()->prepare("SELECT * FROM users WHERE email=?");$s->execute([strtolower(trim($_POST['email']??''))]);$u=$s->fetch();if($u&&password_verify($_POST['password']??'',$u['password_hash'])){session_regenerate_id(true);unset($u['password_hash']);$_SESSION['user']=$u;header('Location: index.php');exit;}$err='Email hoặc mật khẩu không đúng.';}$pageTitle='Đăng nhập';require __DIR__.'/includes/header.php';?><div class="formbox"><h1>Đăng nhập</h1><p class="error"><?=e($err)?></p><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Email</label><input type="email" name="email" required><label>Mật khẩu</label><input type="password" name="password" required><button class="btn">Đăng nhập</button></form><p><a href="register.php">Tạo tài khoản</a></p></div></main></body></html>